public class MontageAsset {
 public string Id {get;set;} public string Path {get;set;} public string Kind {get;set;} public double Duration {get;set;} public bool Audio {get;set;} public int Width {get;set;} public int Height {get;set;}
 public override string ToString(){return (Kind=="audio"?"♫ ":Kind=="image"?"▧ ":"▶ ")+System.IO.Path.GetFileName(Path)+"  •  "+Studio.Time(Duration);}
}
public class MontageTrack {
 public string Id {get;set;} public string Name {get;set;} public string Kind {get;set;} public bool Hidden {get;set;} public bool Muted {get;set;} public bool Locked {get;set;}
}
public class MontageClip {
 public string Id {get;set;} public string Track {get;set;} public string Asset {get;set;} public string Text {get;set;}
 public double Start {get;set;} public double In {get;set;} public double Length {get;set;} public double Speed {get;set;} public double Volume {get;set;}
 public double X {get;set;} public double Y {get;set;} public double Scale {get;set;} public double Rotation {get;set;} public double Opacity {get;set;}
 public int Mask {get;set;} public int Style {get;set;} public int Filter {get;set;} public double Font {get;set;} public double Fade {get;set;}
 public MontageClip(){Length=5;Speed=1;Volume=100;X=Y=50;Scale=100;Opacity=100;Font=64;Text="Ваш текст";}
}
public class MontageDocument {
 public int Version {get;set;} public int Aspect {get;set;} public int Resolution {get;set;} public int Fps {get;set;}
 public List<MontageAsset> Assets {get;set;} public List<MontageTrack> Tracks {get;set;} public List<MontageClip> Items {get;set;}
 public MontageDocument(){Version=1;Fps=30;Assets=new List<MontageAsset>();Tracks=new List<MontageTrack>();Items=new List<MontageClip>();}
 public double Duration {get{return Items.Count==0?5:Math.Max(.1,Items.Max(c=>c.Start+c.Length));}}
}
