 MontageClip SelectedMontage(){return montage.Items.FirstOrDefault(c=>c.Id==montageSelection);}
 MontageTrack TrackOf(MontageClip c){return c==null?null:montage.Tracks.FirstOrDefault(t=>t.Id==c.Track);}
