 void ShowMontage(){Page(true);montageMode=true;montageNav.Background=MC("#302742");montageNav.Foreground=MC("#b59aff");Btn("NavEditor").Background=MC("#191a1f");Btn("NavEditor").Foreground=MC("#a0a0af");UI<Grid>("EditorPage").Visibility=Visibility.Collapsed;montagePage.Visibility=Visibility.Visible;Btn("Export").IsEnabled=montage.Items.Count>0;Btn("Undo").IsEnabled=false;Btn("Redo").IsEnabled=false;RequestMontageFrame();Status("Многодорожечный монтаж • импортируйте видео, аудио или добавьте текст.");}
 void NewMontage(){if(exporting||previewBuilding)return;StopMontagePlayer();SaveMontageRecovery();montage=new MontageDocument();montageSelection=montageTrackSelection=null;montageSession=Id();montageSeek.Value=0;ResetMontageHistory();MontageChanged(false);FillMontageInspector();}
 MontageTrack AddMontageTrack(string kind){if(montage.Tracks.Count>=24)throw new Exception("Поддерживается до 24 дорожек.");var t=new MontageTrack{Id=Id(),Kind=kind,Name=(kind=="video"?"Видео":kind=="audio"?"Аудио":"Текст")+" "+(montage.Tracks.Count+1)};montage.Tracks.Insert(0,t);montageTrackSelection=t.Id;MontageChanged();return t;}
 async Task ImportMontage(string kind){if(exporting||previewBuilding)return;var d=new OpenFileDialog{Multiselect=true,Filter=kind=="audio"?"Аудио|*.mp3;*.wav;*.flac;*.ogg;*.m4a;*.aac|Все файлы|*.*":"Медиа|*.mp4;*.mkv;*.mov;*.ts;*.webm;*.avi;*.m4v;*.mp3;*.wav;*.flac;*.ogg;*.m4a;*.aac;*.png;*.jpg;*.jpeg;*.webp;*.bmp|Все файлы|*.*"};if(d.ShowDialog(window)!=true)return;foreach(var p in d.FileNames)await ProbeMontageAsset(p);ShowMontage();}
 async void AddMontageSource(string path){try{await ProbeMontageAsset(path);ShowMontage();}catch(Exception ex){Status(ex.Message);}}
 async Task<MontageAsset> ProbeMontageAsset(string path){var existing=montage.Assets.FirstOrDefault(entry=>String.Equals(entry.Path,path,StringComparison.OrdinalIgnoreCase));if(existing!=null){montageLibrary.SelectedItem=existing;return existing;}var r=await Run(ffmpeg,"-hide_banner -i "+Q(path),root,null,null);bool image=Regex.IsMatch(Path.GetExtension(path),@"^\.(png|jpe?g|webp|bmp)$",RegexOptions.IgnoreCase);bool video=r.Error.Contains("Video:")&&!Regex.IsMatch(Path.GetExtension(path),@"^\.(mp3|wav|flac|ogg|m4a|aac)$",RegexOptions.IgnoreCase);Match d=Regex.Match(r.Error,@"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)");if(!video&&!r.Error.Contains("Audio:"))throw new Exception("Формат не поддерживается: "+Path.GetFileName(path));double length=image?5:d.Success?double.Parse(d.Groups[1].Value)*3600+double.Parse(d.Groups[2].Value)*60+double.Parse(d.Groups[3].Value,CultureInfo.InvariantCulture):0;if(length<.1)throw new Exception("Не удалось определить длительность медиа или файл короче 0,1 секунды.");var a=new MontageAsset{Id=Id(),Path=Path.GetFullPath(path),Kind=image?"image":video?"video":"audio",Duration=length,Audio=r.Error.Contains("Audio:")};Match dims=Regex.Match(r.Error.Split('\n').FirstOrDefault(line=>line.Contains("Video:"))??"",@"\b(\d{2,5})x(\d{2,5})\b");if(dims.Success){a.Width=int.Parse(dims.Groups[1].Value);a.Height=int.Parse(dims.Groups[2].Value);if(Regex.IsMatch(r.Error,@"rotation of -?90|rotate\s*:\s*-?90")){int swap=a.Width;a.Width=a.Height;a.Height=swap;}}montage.Assets.Add(a);await MontageThumbnail(a);MontageChanged();montageLibrary.SelectedItem=a;if(montage.Items.Count==0)AddSelectedAsset();return a;}
 void AddSelectedAsset(){if(montage.Items.Count>=80)throw new Exception("Поддерживается до 80 клипов.");var asset=montageLibrary.SelectedItem as MontageAsset;if(asset==null){Status("Сначала выберите файл в медиатеке.");return;}string kind=asset.Kind=="audio"?"audio":"video";var t=montage.Tracks.FirstOrDefault(v=>v.Id==montageTrackSelection&&v.Kind==kind&&!v.Locked);if(t==null)t=AddMontageTrack(kind);var c=new MontageClip{Id=Id(),Track=t.Id,Asset=asset.Id,Length=Math.Min(asset.Duration,86400-montageSeek.Value),Start=montageSeek.Value};montage.Items.Add(c);SelectMontage(c);MontageChanged();}
 void AddMontageText(){if(montage.Items.Count>=80)throw new Exception("Поддерживается до 80 клипов.");var t=montage.Tracks.FirstOrDefault(v=>v.Id==montageTrackSelection&&v.Kind=="text"&&!v.Locked);if(t==null)t=AddMontageTrack("text");var c=new MontageClip{Id=Id(),Track=t.Id,Start=montageSeek.Value,Length=5};montage.Items.Add(c);SelectMontage(c);MontageChanged();}
 void SelectMontage(MontageClip c){montageSelection=c==null?null:c.Id;if(c!=null)montageTrackSelection=c.Track;multiTimeline.SelectedId=montageSelection;multiTimeline.SelectedTrack=montageTrackSelection;FillMontageInspector();multiTimeline.InvalidateVisual();}
 bool CanEditMontage(){var c=SelectedMontage();return c!=null&&!TrackOf(c).Locked&&!exporting&&!previewBuilding;}
 void SplitMontage(){if(!CanEditMontage())return;if(montage.Items.Count>=80){Status("Поддерживается до 80 клипов.");return;}var c=SelectedMontage();double cut=montageSeek.Value-c.Start;if(cut<.1||cut>c.Length-.1){Status("Поставьте курсор внутрь клипа, отступив от краёв 0,1 секунды.");return;}var other=CloneMontageClip(c);other.Id=Id();other.Start+=cut;other.In+=cut*c.Speed;other.Length-=cut;c.Length=cut;montage.Items.Add(other);SelectMontage(other);MontageChanged();FlushMontageHistory();}
 MontageClip CloneMontageClip(MontageClip c){return new JavaScriptSerializer().Deserialize<MontageClip>(new JavaScriptSerializer().Serialize(c));}
 void DuplicateMontage(){if(!CanEditMontage()||montage.Items.Count>=80)return;var c=CloneMontageClip(SelectedMontage());c.Id=Id();c.Start+=c.Length;montage.Items.Add(c);SelectMontage(c);MontageChanged();FlushMontageHistory();}
 void DeleteMontage(){if(!CanEditMontage())return;montage.Items.Remove(SelectedMontage());SelectMontage(null);MontageChanged();FlushMontageHistory();}
 void MontageChanged(bool edit=true){if(multiTimeline==null)return;multiTimeline.Document=montage;multiTimeline.Height=40+montage.Tracks.Count*66;multiTimeline.InvalidateVisual();montageUpdating=true;var keepAsset=montageLibrary.SelectedItem as MontageAsset;montageLibrary.ItemsSource=null;montageLibrary.ItemsSource=montage.Assets;if(keepAsset!=null)montageLibrary.SelectedItem=montage.Assets.FirstOrDefault(a=>a.Id==keepAsset.Id);montageSeek.Maximum=montage.Duration;montageUpdating=false;montageTime.Text=Time(montageSeek.Value)+" / "+Time(montage.Duration);if(montageMode)Btn("Export").IsEnabled=montage.Items.Count>0;if(edit&&!montageRestoring){montageHistoryDelay.Stop();montageHistoryDelay.Start();}RequestMontageFrame();}
 void RequestMontageFrame(){if(!montageMode||selfTesting)return;montageFramePending=true;montageDelay.Stop();montageDelay.Start();}
 string MontageSnapshot(){return new JavaScriptSerializer().Serialize(montage);}
 void ResetMontageHistory(){montageHistory.Clear();montageHistoryIndex=-1;FlushMontageHistory();}
 void FlushMontageHistory(){if(montageRestoring)return;string state=MontageSnapshot();if(montageHistoryIndex>=0&&montageHistory[montageHistoryIndex]==state)return;if(montageHistoryIndex+1<montageHistory.Count)montageHistory.RemoveRange(montageHistoryIndex+1,montageHistory.Count-montageHistoryIndex-1);montageHistory.Add(state);if(montageHistory.Count>60)montageHistory.RemoveAt(0);montageHistoryIndex=montageHistory.Count-1;}
 void MontageUndo(int dir){if(exporting||previewBuilding)return;montageHistoryDelay.Stop();FlushMontageHistory();int index=montageHistoryIndex+dir;if(index<0||index>=montageHistory.Count)return;montageHistoryIndex=index;montageRestoring=true;montage=new JavaScriptSerializer().Deserialize<MontageDocument>(montageHistory[index]);MontageChanged(false);FillMontageInspector();montageRestoring=false;}
 Project MontageProject(){return new Project{Version=4,Montage=montage,Clips=new List<Clip>(),Settings=new EditSettings()};}
 void SaveMontage(){if(montageBusy())return;var d=new SaveFileDialog{Filter="Проект TwitchGrab|*.tgstudio",DefaultExt=".tgstudio",FileName="Монтаж.tgstudio"};if(d.ShowDialog(window)!=true)return;AtomicProjectWrite(d.FileName,new JavaScriptSerializer().Serialize(MontageProject()));Status("Проект дорожек сохранён. Исходные файлы хранятся отдельно.");}
 bool montageBusy(){return exporting||previewBuilding||loading;}
 void SaveMontageRecovery(){if(montage.Items.Count==0||montageBusy()||selfTesting)return;try{string state=new JavaScriptSerializer().Serialize(MontageProject());if(state==montageSavedSnapshot)return;AtomicProjectWrite(Path.Combine(recoveryRoot,"montage-"+montageSession+".tgstudio"),state);AtomicProjectWrite(Path.Combine(recoveryRoot,"montage-last.tgstudio"),state);montageSavedSnapshot=state;}catch(Exception ex){Status("Автокопия дорожек: "+ex.Message);}}
 async Task LoadMontage(MontageDocument doc){ValidateMontage(doc,false);foreach(var a in doc.Assets){if(!File.Exists(a.Path)){var d=new OpenFileDialog{Title="Найдите файл: "+Path.GetFileName(a.Path),CheckFileExists=true};if(d.ShowDialog(window)!=true)return;a.Path=d.FileName;}}ValidateMontage(doc,true);SaveMontageRecovery();montage=doc;montageSession=Id();montageSelection=montageTrackSelection=null;ResetMontageHistory();MontageChanged(false);FillMontageInspector();ShowMontage();foreach(var a in doc.Assets.Take(24))await MontageThumbnail(a);Status("Проект с дорожками открыт.");}
 async Task MontageThumbnail(MontageAsset a){if(multiTimeline.Pictures.ContainsKey(a.Id))return;string job=Path.Combine(cacheRoot,Id());Directory.CreateDirectory(job);try{string output=Path.Combine(job,"thumb.png");string args=a.Kind=="audio"?"-t 30 -i "+Q(a.Path)+" -filter_complex aformat=channel_layouts=mono,showwavespic=s=320x44:colors=0x71d6b4 -frames:v 1 -update 1 "+Q(output):"-i "+Q(a.Path)+" -frames:v 1 -vf scale=128:-2 -update 1 "+Q(output);var r=await Run(ffmpeg,"-hide_banner -loglevel error -nostdin "+args,job,null,null);if(r.Code==0){multiTimeline.Pictures[a.Id]=ReadBitmap(output);multiTimeline.InvalidateVisual();}}catch{}finally{CleanJob(job);}}

 void DetachMontageAudio(){if(!CanEditMontage())return;var c=SelectedMontage();var a=AssetOf(c);if(TrackOf(c).Kind!="video"||a==null||!a.Audio){Status("Выберите видеоклип с исходным звуком.");return;}if(montage.Items.Count>=80)return;var asset=new MontageAsset{Id=Id(),Path=a.Path,Kind="audio",Duration=a.Duration,Audio=true};montage.Assets.Add(asset);var t=AddMontageTrack("audio");var sound=CloneMontageClip(c);sound.Id=Id();sound.Asset=asset.Id;sound.Track=t.Id;sound.Volume=c.Volume;c.Volume=0;montage.Items.Add(sound);SelectMontage(sound);MontageChanged();FlushMontageHistory();Status("Звук отделён: редактируйте аудиоклип независимо от видео.");}

